import { inject, ProviderToken } from "@angular/core";
import { Observable, of } from "rxjs";

import { BaseMockService } from "../../mock/service/base-mock.service";
import { BaseApiModel } from "../model/base-api.model";
import { ResponseApiModel } from "../model/response-api.model";

export class BaseApiService<TModel extends BaseApiModel> {
    baseMockService: BaseMockService<TModel>;

    constructor(private readonly token: ProviderToken<BaseMockService<TModel>>) {
        this.baseMockService = inject(token);
    }

    create(itemToCreate: Omit<TModel, "id">): Observable<ResponseApiModel<TModel | undefined>> {
        return of(this.baseMockService.create(itemToCreate));
    }

    read(id: number): Observable<ResponseApiModel<TModel | undefined>> {
        return of(this.baseMockService.read(id));
    }

    readAll(): Observable<ResponseApiModel<TModel[]>> {
        return of(this.baseMockService.readAll());
    }

    update(itemToUpdate: TModel): Observable<ResponseApiModel<TModel | undefined>> {
        return of(this.baseMockService.update(itemToUpdate));
    }

    delete(id: number): Observable<ResponseApiModel<TModel | undefined>> {
        return of(this.baseMockService.delete(id));
    }
}

import { BaseMockModel } from "../model/base-mock.model";
import { ResponseMockModel } from "../model/response-mock.model";

export class BaseMockService<TModel extends BaseMockModel> {
    nextId = 0;

    constructor(public items: TModel[]) {}

    create(itemToCreate: Omit<TModel, "id">): ResponseMockModel<TModel> {
        const newUser = { ...itemToCreate, id: this.nextId++ } as TModel;
        this.items.push(newUser);
        const response: ResponseMockModel<TModel> = {
            success: true,
            message: "Successfully created item.",
            body: newUser
        };
        return response;
    }

    read(id: number): ResponseMockModel<TModel | undefined> {
        const item = this.items.find(item => item.id === id);
        if (item) {
            const response: ResponseMockModel<TModel | undefined> = {
                success: true,
                message: "Successfully retrieved item.",
                body: item
            };
            return response;
        }
        const response: ResponseMockModel<TModel | undefined> = {
            success: false,
            message: "Item not found.",
            body: undefined
        };
        return response;
    }

    readAll(): ResponseMockModel<TModel[]> {
        if (this.items.length === 0) {
            const response: ResponseMockModel<TModel[]> = {
                success: false,
                message: "No items found.",
                body: []
            };
            return response;
        }
        const response: ResponseMockModel<TModel[]> = {
            success: true,
            message: "Successfully retrieved all items.",
            body: this.items
        };
        return response;
    }

    update(itemToUpdate: TModel): ResponseMockModel<TModel | undefined> {
        const itemToUpdateExists = this.items.some(item => item.id === itemToUpdate.id);
        if (itemToUpdateExists) {
            this.items = this.items.map(item => item.id === itemToUpdate.id ? itemToUpdate : item);
            const response: ResponseMockModel<TModel | undefined> = {
                success: true,
                message: "Successfully updated item.",
                body: itemToUpdate
            };
            return response;
        }
        const response: ResponseMockModel<TModel | undefined> = {
            success: false,
            message: "Item to update not found.",
            body: undefined
        };
        return response;
    }

    delete(id: number): ResponseMockModel<TModel | undefined> {
        const itemToDelete = this.items.find(item => item.id === id);
        if (itemToDelete) {
            this.items = this.items.filter(item => item.id !== id);
            const response: ResponseMockModel<TModel | undefined> = {
                success: true,
                message: "Successfully deleted item.",
                body: itemToDelete
            };
            return response;
        }
        const response: ResponseMockModel<TModel | undefined> = {
            success: false,
            message: "Item not found.",
            body: undefined
        };
        return response;
    }
}

import { inject, ProviderToken } from "@angular/core";
import { Store } from "@ngxs/store";
import { of, switchMap } from "rxjs";

import { BaseApiModel } from "../api/model/base-api.model";
import { BaseStoreModel } from "../store/model/base-store.model";
import { BaseStoreAction } from "../store/action/base-store.action";
import { BaseApiService } from "../api/service/base-api.service";

type TBaseGetStatus = <TModel extends BaseApiModel>(state: BaseStoreModel<TModel>) => { success: boolean; message: string; };
type TBaseGetIsLoading = <TModel extends BaseApiModel>(state: BaseStoreModel<TModel>) => boolean;
type TBaseGetItems = <TModel extends BaseApiModel>(state: BaseStoreModel<TModel>) => TModel[];
type TBaseGetSelectedItem = <TModel extends BaseApiModel>(state: BaseStoreModel<TModel>) => TModel | undefined;
type TBaseGetColumns = <TModel extends BaseApiModel>(state: BaseStoreModel<TModel>) => BaseStoreModel<TModel>["columns"];

export class BaseService<TModel extends BaseApiModel> {
    baseApiService: BaseApiService<TModel>;

    store = inject(Store);

    constructor(
        private readonly token: ProviderToken<BaseApiService<TModel>>,
        private readonly baseGetStatus: TBaseGetStatus,
        private readonly baseGetIsLoading: TBaseGetIsLoading,
        private readonly baseGetItems: TBaseGetItems,
        private readonly baseGetSelectedItem: TBaseGetSelectedItem,
        private readonly baseGetColumns: TBaseGetColumns,
        private readonly baseSetStatus: typeof BaseStoreAction.SetStatus,
        private readonly baseSetIsLoading: typeof BaseStoreAction.SetIsLoading,
        private readonly baseSetItems: typeof BaseStoreAction.SetItems<TModel>,
        private readonly baseAddItem: typeof BaseStoreAction.AddItem<TModel>,
        private readonly baseUpdateItem: typeof BaseStoreAction.UpdateItem<TModel>,
        private readonly baseDeleteItem: typeof BaseStoreAction.DeleteItem,
        private readonly baseSetSelectedItem: typeof BaseStoreAction.SetSelectedItem<TModel>
    ) {
        this.baseApiService = inject(token);
    }

    getStatus() {
        return this.store.select(this.baseGetStatus);
    }

    getIsLoading() {
        return this.store.select(this.baseGetIsLoading);
    }

    getItems() {
        return this.store.select(this.baseGetItems);
    }

    getSelectedItem() {
        return this.store.select(this.baseGetSelectedItem);
    }

    getColumns() {
        return this.store.select(this.baseGetColumns);
    }

    create(itemToCreate: Omit<TModel, "id">) {
        return of(true).pipe(
            switchMap(() => this.store.dispatch(new this.baseSetIsLoading(true))),
            switchMap(() => this.baseApiService.create(itemToCreate)),
            switchMap(response => {
                if (response.body) {
                    this.store.dispatch(new this.baseAddItem(response.body));
                }
                return of(response);
            }),
            switchMap(response => {
                const { success, message } = response;
                this.store.dispatch(new this.baseSetStatus(success, message));
                return of(true);
            }),
            switchMap(() => this.store.dispatch(new this.baseSetIsLoading(false)))
        );
    }

    read(id: number) {
        return of(true).pipe(
            switchMap(() => this.store.dispatch(new this.baseSetIsLoading(true))),
            switchMap(() => this.baseApiService.read(id)),
            switchMap(response => {
                const { success, message } = response;
                this.store.dispatch(new this.baseSetStatus(success, message));
                return of(response.body);
            }),
            switchMap(body => {
                this.store.dispatch(new this.baseSetIsLoading(false));
                return of(body);
            })
        );
    }

    readAll() {
        return of(true).pipe(
            switchMap(() => this.store.dispatch(new this.baseSetIsLoading(true))),
            switchMap(() => this.baseApiService.readAll()),
            switchMap(response => {
                this.store.dispatch(new this.baseSetItems(response.body));
                return of(response);
            }),
            switchMap(response => {
                const { success, message } = response;
                this.store.dispatch(new this.baseSetStatus(success, message));
                return of(true);
            }),
            switchMap(() => this.store.dispatch(new this.baseSetIsLoading(false)))
        );
    }

    update(itemToUpdate: TModel) {
        return of(true).pipe(
            switchMap(() => this.store.dispatch(new this.baseSetIsLoading(true))),
            switchMap(() => this.baseApiService.update(itemToUpdate)),
            switchMap(response => {
                if (response.body) {
                    this.store.dispatch(new this.baseUpdateItem(response.body));
                }
                return of(response);
            }),
            switchMap(response => {
                const { success, message } = response;
                this.store.dispatch(new this.baseSetStatus(success, message));
                return of(true);
            }),
            switchMap(() => this.store.dispatch(new this.baseSetIsLoading(false)))
        );
    }

    delete(id: number) {
        return of(true).pipe(
            switchMap(() => this.store.dispatch(new this.baseSetIsLoading(true))),
            switchMap(() => this.baseApiService.delete(id)),
            switchMap(response => {
                if (response.body) {
                    this.store.dispatch(new this.baseDeleteItem(response.body.id));
                }
                return of(response);
            }),
            switchMap(response => {
                const { success, message } = response;
                this.store.dispatch(new this.baseSetStatus(success, message));
                return of(true);
            }),
            switchMap(() => this.store.dispatch(new this.baseSetIsLoading(false)))
        );
    }

    selectItem(itemToSelect: TModel) {
        return of(true).pipe(
            switchMap(() => this.store.dispatch(new this.baseSetIsLoading(true))),
            switchMap(() => this.store.dispatch(new this.baseSetSelectedItem(itemToSelect))),
            switchMap(() => this.store.dispatch(new this.baseSetIsLoading(false)))
        );
    }
}

